const AWS = require('aws-sdk');
const ddb = new AWS.DynamoDB.DocumentClient();

async function saveEvent(event) {
  const params = {
    TableName: process.env.TABLE_NAME,
    Item: {
      deviceId: event.deviceId,
      eventId: event.eventId,
      timestamp: event.timestamp,
      data: event.data
    },
    ConditionExpression: 'attribute_not_exists(eventId)'
  };

  try {
    await ddb.put(params).promise();
  } catch (error) {
    if (error.code !== 'ConditionalCheckFailedException') {
      throw error;
    }
  }
}
```

## Why This Is Asked
This question probes practical privacy controls in streaming pipelines, enforcing field-level masking without breaking analytics.

## Key Concepts
- Field-level masking; deterministic tokens; per-stream salt
- Schema evolution with Glue Schema Registry
- PII handling in cross-region Kinesis→Lambda→S3
- Auditability via DynamoDB; LocalStack testing

## Code Example
```javascript
function maskPiI(value, salt){
  if(!value) return value;
  const crypto = require('crypto');
  const h = crypto.createHash('sha256');
  h.update(String(salt));
  h.update(value);
  return h.digest('hex').slice(0, 16);
}
```

